def kmp_search(text, pattern):
    if not pattern:
        return 0
    failure = [0] * len(pattern)
    k = 0
    for i in range(1, len(pattern)):
        while k > 0 and pattern[k] != pattern[i]:
            k = failure[k - 1]
        if pattern[k] == pattern[i]:
            k += 1
        failure[i] = k
    k = 0
    for i, ch in enumerate(text):
        while k > 0 and pattern[k] != ch:
            k = failure[k - 1]
        if pattern[k] == ch:
            k += 1
        if k == len(pattern):
            return i - k + 1
    return -1

